def amicable_numbers_sum(limit: int) -> int:
    def get_sum_divisors(n):
        s = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                s += i
                if i*i != n:
                    s += n // i
        return s

    total_sum = 0
    for a in range(1, limit + 1):
        b = get_sum_divisors(a)
        if b > 1 and a != b and get_sum_divisors(b) == a:
            total_sum += a

    return total_sum

# Test case
assert amicable_numbers_sum(999) == 504
